func TestPassword(t *testing.T) {
	hash, err := HashPassword("correct horse battery staple")
	if err != nil {
		t.Fatal(err)
	}
	if ok, rehash := VerifyPassword(hash, "correct horse battery staple"); !ok || rehash {
		t.Fatalf("verify = %v %v", ok, rehash)
	}
	if ok, _ := VerifyPassword(hash, "correct horse battery stapler"); ok {
		t.Fatal("a wrong password was accepted")
	}
	other, _ := HashPassword("correct horse battery staple")
	if other == hash {
		t.Fatal("two hashes share a salt")
	}
	for _, bad := range []string{"", "plain", strings.Replace(hash, passwordScheme, "md5", 1), hash[:len(hash)-4]} {
		if ok, _ := VerifyPassword(bad, "correct horse battery staple"); ok {
			t.Fatalf("malformed hash %q was accepted", bad)
		}
	}
	salt := []byte("0123456789abcdef")
	key, _ := pbkdf2.Key(sha256.New, "secret-password", salt, 1000, keyBytes)
	weak := passwordScheme + "$1000$" + base64.RawStdEncoding.EncodeToString(salt) + "$" + base64.RawStdEncoding.EncodeToString(key)
	if ok, rehash := VerifyPassword(weak, "secret-password"); !ok || !rehash {
		t.Fatalf("hash with fewer iterations = %v %v, want a match that needs rehashing", ok, rehash)
	}
}

